import { Effect } from "effect"
import { FetchHttpClient, HttpClient } from "effect/unstable/http"

export const loadExchangeRate = (currency: string) =>
  Effect.gen(function*() {
    const client = yield* HttpClient.HttpClient
    const response = yield* client.get(
      `https://rates.internal.example/latest?currency=${encodeURIComponent(currency)}`
    )
    const payload = yield* response.json

    if (
      typeof payload !== "object" ||
      payload === null ||
      !("rate" in payload) ||
      typeof payload.rate !== "number"
    ) {
      return yield* Effect.fail(new Error(`Invalid rate for ${currency}`))
    }

    return payload.rate
  }).pipe(Effect.provide(FetchHttpClient.layer))

const program = Effect.gen(function*() {
  const euroRate = yield* loadExchangeRate("EUR")
  const yenRate = yield* loadExchangeRate("JPY")

  yield* Effect.log(`EUR transfer estimate: ${500 * euroRate}`)
  yield* Effect.log(`JPY transfer estimate: ${500 * yenRate}`)
})

Effect.runPromise(program)

